<?php
namespace qqworld_collector\module\auto_save_attachments; use qqworld_collector\lib; use PHPImageWorkshop\ImageWorkshop; use GifCreator; use GifFrameExtractor; class save_attachment extends lib { var $options; var $settings; var $download_args; var $log_id = 'auto-save-attachment'; var $thumbnail_id = -1; var $remote_attachments; var $has_remote_attachments; var $has_missing_attachments; var $post_ID; var $save_type; var $image_paste; var $local_mark; var $convert_file_format; var $rest_api; public function __construct() { add_filter( 'post_updated_messages', array($this, 'post_updated_messages') ); add_filter( 'qqworld-collector-save-remote-attachment-from-content-before', array($this, 'change_attachment_url_to_permalink'), 10, 2 ); add_filter( 'qqworld-collector-save-remote-attachment-from-content', array($this, 'save_remote_attachment'), 10, 2 ); add_filter( 'qqworld-collector-auto-save-attachment-filename', array($this, 'custom_filename_structure'), 10, 2 ); add_filter( 'qqworld-collector-auto-save-attachment-filename', array($this, 'string_compatible_vietnamese_to_english'), 10, 2 ); add_filter( 'qqworld-collector-auto-save-attachment-remote-attachment', array($this, 'copping_image') ); add_filter( 'qqworld-collector-auto-save-attachment-remote-attachment', array($this, 'flip_horizontal_image') ); add_filter( 'qqworld-collector-auto-save-attachment-remote-attachment', array($this, 'automatic_reduction') ); add_filter( 'wp_handle_upload_prefilter', array($this, 'wp_handle_upload_prefilter') ); add_action( 'wp_loaded', array($this, 'initial') ); add_filter( 'big_image_size_threshold', '__return_false' ); if (class_exists('imagick')) $this->image_types[] = 'image/svg+xml'; add_action( 'wp_insert_post', array($this, 'finish_title_alt'), 11, 3 ); add_action( 'wp_insert_comment', array($this, 'save_attachment_in_comment'), 11, 2 ); add_action( 'edit_comment', array($this, 'save_attachment_in_comment'), 11, 2 ); } public function initial() { $this->allowed_image_types = $this->get_mime_types(); } public function includes() { include __DIR__ . DIRECTORY_SEPARATOR . 'image-paste.php'; $this->image_paste = new image_paste; $this->image_paste->options = $this->options; $this->image_paste->core = $this; $this->image_paste->init(); include __DIR__ . DIRECTORY_SEPARATOR . 'local-mark.php'; $this->local_mark = new local_mark; $this->local_mark->options = $this->options; $this->local_mark->core = $this; $this->local_mark->init(); include __DIR__ . DIRECTORY_SEPARATOR . 'convert-file-format.php'; $this->convert_file_format = new convert_file_format; $this->convert_file_format->options = $this->options; $this->convert_file_format->core = $this; $this->convert_file_format->init(); include __DIR__ . DIRECTORY_SEPARATOR . 'rest_api.php'; $this->rest_api = new rest_api; $this->rest_api->options = $this->options; $this->rest_api->core = $this; $this->rest_api->init(); } public function mime_types($mime_types) { $mime_types['webp'] = 'image/webp'; $mime_types['webm'] = 'video/webm'; $mime_types['weba'] = 'audio/webm'; $mime_types['svg'] = 'image/svg+xml'; $mime_types['apk'] = 'application/vnd.android.package-archive'; $mime_types['jfif'] = 'image/jfif+xml'; $mime_types['doc'] = 'application/msword'; $mime_types['torrent'] = 'application/x-bittorrent'; $mime_types['ppt'] = 'application/vnd.ms-powerpoint'; $mime_types['xls'] = 'application/vnd.ms-excel'; $mime_types['rar'] = 'application/x-rar-compressed'; $mime_types['psd'] = 'application/x-photoshop'; $mime_types['heic'] = 'image/heic'; $mime_types['heif'] = 'image/heif'; $mime_types['heics'] = 'image/heic-sequence'; $mime_types['heifs'] = 'image/heif-sequence'; $mime_types['avif'] = 'image/avif'; $mime_types['avis'] = 'image/avis'; $mime_types['ico'] = 'image/x-icon'; $mime_types['docx'] = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'; $mime_types['xlsx'] = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'; $mime_types['pptx'] = 'application/vnd.openxmlformats-officedocument.presentationml.presentation'; $mime_types['ttf'] = 'font/ttf'; $mime_types['woff'] = 'font/woff'; $mime_types['woff2'] = 'font/woff2'; $mime_types['otf'] = 'font/otf'; return $mime_types; } public function ext2type($ext) { if (!isset($ext['font'])) $ext['font'] = array('ttf', 'woff', 'woff2', 'otf'); else $ext['font'] = array_merge($ext['font'], array('ttf', 'woff', 'woff2', 'otf')); return $ext; } public function wp_check_filetype_and_ext($data, $file, $filename, $mimes) { if (empty($data['ext']) || empty($data['type']) || !$data['proper_filename']) { $wp_filetype = wp_check_filetype($filename, $mimes); if ($wp_filetype['ext'] == 'avif') { $data['ext'] = 'avif'; $data['type'] = 'image/avif'; } } return $data; } public function file_is_displayable_image($result, $path) { if ( function_exists('mime_content_type') ) { $type = mime_content_type($path); if ($type == 'image/webp') { $result = true; } } return $result; } public function crop($blob, $top=0, $left=0, $right=0, $bottom=0) { if ($top || $left || $right || $bottom) { if (class_exists('\Imagick')) { $x = $top; $y = $left; $imagick = new \Imagick; $imagick->readImageBlob($blob); $size = $imagick->getImagePage(); $width = $size['width']-$left-$right; $height = $size['height']-$top-$bottom; $imagick->cropImage($width, $height, $x, $y); $blob = $imagick->getImageBlob(); $imagick->destroy(); } else { $x = $top; $y = $left; $size = getimagesizefromstring($blob); if (in_array($size['mime'], array('image/jpeg','image/png','image/gif','image/webp','image/bmp','image/vnd.wap.wbmp'))) { $width = $size[0]-$left-$right; $height = $size[1]-$top-$bottom; $image = imagecreatefromstring($blob); $final_width = $width; $final_height = round($final_width * $height / $width); $new_image = imagecreatetruecolor($final_width, $final_height); imagecopyresampled($new_image, $image, 0, 0, $x, $y, $final_width, $final_height, $width, $height); ob_start(); switch ($size['mime']) { case 'image/jpeg': imagejpeg($new_image); break; case 'image/png': imagepng($new_image); break; case 'image/gif': imagegif($new_image); break; case 'image/webp': imagewebp($new_image); break; case 'image/bmp': imagebmp($new_image); break; case 'image/vnd.wap.wbmp': imagewbmp($new_image); break; } $blob = ob_get_contents(); ob_end_clean(); imagedestroy($image); imagedestroy($new_image); } } } return $blob; } public function init() { $this->includes(); if ( !$this->core->activated ) return; add_filter( 'mime_types', array($this, 'mime_types') ); add_action( 'upload_mimes', array($this, 'mime_types') ); add_action( 'ext2type', array($this, 'ext2type') ); add_filter( 'wp_check_filetype_and_ext', array($this, 'wp_check_filetype_and_ext'), 10, 4 ); add_filter( 'file_is_displayable_image', array($this, 'file_is_displayable_image'), 10, 2 ); add_filter( 'wp_handle_upload', array($this, 'wp_handle_upload'), 10, 2 ); if ($this->options->qc_asa_general_mode == 'manual') { add_action( 'qqworld-collector-add-media-buttons-for-menual-mode', array($this, 'add_media_buttons_for_menual_mode') ); add_action( 'wp_ajax_qqworld-collector-auto-save-attachments-manually', array($this, 'save_remote_attachments_manually') ); add_action( 'wp_ajax_nopriv_qqworld-collector-auto-save-attachments-manually', array($this, 'save_remote_attachments_manually') ); add_action( 'wp_ajax_qqworld-collector-grab-remote-attachment', array($this, 'ajax_grab_attachment') ); add_action( 'wp_ajax_nopriv_qqworld-collector-grab-remote-attachment', array($this, 'ajax_grab_attachment') ); } else { add_action( 'wp_ajax_qqworld-collector-auto-save-attachments-get-auto-saved-results', array($this, 'print_auto_saved_results') ); add_action( 'wp_ajax_nopriv_qqworld-collector-auto-save-attachments-get-auto-saved-results', array($this, 'print_auto_saved_results') ); } add_action( 'wp_ajax_qqworld-collector-bulk-set-featured-images', array($this, 'bulk_set_featured_images') ); add_action( 'wp_ajax_nopriv_qqworld-collector-bulk-set-featured-images', array($this, 'bulk_set_featured_images') ); add_action( 'wp_insert_post', array($this, 'set_default_featured_image'), 99, 3 ); add_filter( 'qqworld-collector-save-attachment-filename', array($this, 'save_attachment_filename'), 10, 2 ); if ($this->options->qc_asa_general_schedule_publish == '1') add_action( 'publish_future_post', array($this, 'fetch_images_when_saving') ); if ( defined('XMLRPC_REQUEST')) { if ($this->options->qc_asa_general_remote_publishing == '1') { $this->options->qc_asa_general_mode = 'auto'; global $wp_post_statuses; $post_status = array_keys($wp_post_statuses); unset($post_status['auto-draft']); unset($post_status['inherit']); unset($post_status['trash']); $this->options->qc_asa_general_when = $post_status; } else { $this->options->qc_asa_general_mode = 'manual'; } } if ($this->options->qc_asa_general_mode == 'auto') $this->add_actions(); add_action( 'wp_insert_post', array($this, 'fetch_images_from_post_meta'), 10, 2 ); $headers = array(); $this->download_args = !empty($headers) ? array( 'headers' => implode("\n", $headers) ) : array(); if ($this->options->qc_proxy_enabled == 1) { $this->download_args['proxy'] = 1; } add_filter( 'qqworld-collector-data-before-create-product', array($this, 'parse_data_before_create_product') ); } public function wp_handle_upload($upload, $context) { switch ($upload['type']) { case 'image/avif': if ( !$this->options->qc_asa_filter_convert_file_type_avif ) break; $file = file_get_contents($upload['file']); $file = apply_filters( 'qqworld-collector-convert-file-format', $file, 'avif', 'jpeg' ); unlink($upload['file']); $upload['file'] = preg_replace('/\.[^\.]*$/', '.jpg', $upload['file']); $upload['url'] = preg_replace('/\.[^\.]*$/', '.jpg', $upload['url']); $upload['type'] = 'image/jpeg'; file_put_contents($upload['file'], $file); break; case 'image/jpeg': if ( !$this->options->qc_asa_filter_convert_file_type_jpg ) break; $file = file_get_contents($upload['file']); $file = apply_filters( 'qqworld-collector-convert-file-format', $file, 'jpeg', 'webp' ); unlink($upload['file']); $upload['file'] = preg_replace('/\.[^\.]*$/', '.webp', $upload['file']); $upload['url'] = preg_replace('/\.[^\.]*$/', '.webp', $upload['url']); $upload['type'] = 'image/webp'; file_put_contents($upload['file'], $file); break; case 'image/png': if ( !$this->options->qc_asa_filter_convert_file_type_png ) break; $file = file_get_contents($upload['file']); $file = apply_filters( 'qqworld-collector-convert-file-format', $file, 'png', 'webp' ); unlink($upload['file']); $upload['file'] = preg_replace('/\.[^\.]*$/', '.webp', $upload['file']); $upload['url'] = preg_replace('/\.[^\.]*$/', '.webp', $upload['url']); $upload['type'] = 'image/webp'; file_put_contents($upload['file'], $file); break; case 'image/x-ms-bmp': case 'image/bmp': if ( !$this->options->qc_asa_filter_convert_file_type_bmp ) break; $file = file_get_contents($upload['file']); $file = apply_filters( 'qqworld-collector-convert-file-format', $file, 'bmp', 'jpeg' ); unlink($upload['file']); $upload['file'] = preg_replace('/\.[^\.]*$/', '.jpg', $upload['file']); $upload['url'] = preg_replace('/\.[^\.]*$/', '.jpg', $upload['url']); $upload['type'] = 'image/jpeg'; file_put_contents($upload['file'], $file); break; case 'image/webp': if ( !$this->options->qc_asa_filter_convert_file_type_webp ) break; $file = file_get_contents($upload['file']); $file = apply_filters( 'qqworld-collector-convert-file-format', $file, 'webp', 'jpeg' ); unlink($upload['file']); $upload['file'] = preg_replace('/\.[^\.]*$/', '.jpg', $upload['file']); $upload['url'] = preg_replace('/\.[^\.]*$/', '.jpg', $upload['url']); $upload['type'] = 'image/jpeg'; file_put_contents($upload['file'], $file); break; } return $upload; } public function add_actions() { if (!$this->core->activated || has_action( 'wp_insert_post', array($this, 'fetch_images_when_saving') )) return; add_action( 'wp_insert_post', array($this, 'fetch_images_when_saving'), 10, 2 ); } public function remove_actions() { if (!$this->core->activated || !has_action( 'wp_insert_post', array($this, 'fetch_images_when_saving') )) return; remove_action( 'wp_insert_post', array($this, 'fetch_images_when_saving'), 10, 2 ); } public function add_media_buttons_for_menual_mode() { global $pagenow; if ( current_user_can( $this->options->qc_authorization_who_can_use ) && in_array($pagenow, array('post.php', 'post-new.php')) ) { print '<button type="button" id="save-remote-attachments-button" class="button save_remote_images" title="' . __('Save Remote Attachments', $this->text_domain) .'">' . __('Save Remote Attachments', $this->text_domain) . '</button>'; } } public function utf8_urldecode($str) { $str = preg_replace("/%u([0-9a-f]{3,4})/i", "&#x\\\\1;", urldecode($str)); return $str; } public function save_remote_attachments_manually() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) { $results = array( 'success' => 0 ); exit; } set_time_limit($this->options->qc_stress_timeout); if (!defined('COLLECTING')) define('COLLECTING', true); if (!isset($_POST['mode'])) { $results = array( 'success' => 0 ); exit; } $mode = $_REQUEST['mode']; switch ($mode) { case 'get-remote-attachments-list': $post_id = $_REQUEST['post_id']; $this->post_id = $post_id; $this->current_post_id = $post_id; if (is_array($_POST['content'])) { $post_content = $_POST['content']; $remote_attachments = array(); $missing_attachments = array(); $delete_attachments = array(); foreach ($post_content as $clientId => &$content) { $content = stripslashes($content); list($current_remote_attachments, $current_missing_attachments, $current_delete_attachments) = $this->get_remote_attachments($content); if (!empty($current_remote_attachments)) $remote_attachments[$clientId] = $current_remote_attachments; if (!empty($current_missing_attachments)) $missing_attachments[$clientId] = $current_missing_attachments; if (!empty($current_delete_attachments)) $delete_attachments[$clientId] = $current_delete_attachments; } } else { $post_content = stripslashes($_POST['content']); $post_content = $this->utf8_urldecode($this->utf8_urldecode($post_content)); list($remote_attachments, $missing_attachments, $delete_attachments) = $this->get_remote_attachments($post_content); } $results = array( 'success' => 1, 'content' => $post_content, 'remote_attachments' => $remote_attachments, 'missing_attachments' => $missing_attachments, 'delete_attachments' => $delete_attachments ); break; } print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function string_compatible_vietnamese_to_english($str, $args) { $str = preg_replace("/(à|á|ạ|ả|ã|â|ầ|ấ|ậ|ẩ|ẫ|ă|ằ|ắ|ặ|ẳ|ẵ)/", 'a', $str); $str = preg_replace("/(è|é|ẹ|ẻ|ẽ|ê|ề|ế|ệ|ể|ễ)/", 'e', $str); $str = preg_replace("/(ì|í|ị|ỉ|ĩ)/", 'i', $str); $str = preg_replace("/(ò|ó|ọ|ỏ|õ|ô|ồ|ố|ộ|ổ|ỗ|ơ|ờ|ớ|ợ|ở|ỡ)/", 'o', $str); $str = preg_replace("/(ù|ú|ụ|ủ|ũ|ư|ừ|ứ|ự|ử|ữ)/", 'u', $str); $str = preg_replace("/(ỳ|ý|ỵ|ỷ|ỹ)/", 'y', $str); $str = preg_replace("/(đ)/", 'd', $str); $str = preg_replace("/(À|Á|Ạ|Ả|Ã|Â|Ầ|Ấ|Ậ|Ẩ|Ẫ|Ă|Ằ|Ắ|Ặ|Ẳ|Ẵ)/", 'A', $str); $str = preg_replace("/(È|É|Ẹ|Ẻ|Ẽ|Ê|Ề|Ế|Ệ|Ể|Ễ)/", 'E', $str); $str = preg_replace("/(Ì|Í|Ị|Ỉ|Ĩ)/", 'I', $str); $str = preg_replace("/(Ò|Ó|Ọ|Ỏ|Õ|Ô|Ồ|Ố|Ộ|Ổ|Ỗ|Ơ|Ờ|Ớ|Ợ|Ở|Ỡ)/", 'O', $str); $str = preg_replace("/(Ù|Ú|Ụ|Ủ|Ũ|Ư|Ừ|Ứ|Ự|Ử|Ữ)/", 'U', $str); $str = preg_replace("/(Ỳ|Ý|Ỵ|Ỷ|Ỹ)/", 'Y', $str); $str = preg_replace("/(Đ)/", 'D', $str); return $str; } public function automatic_reduction($remote_attachment) { $width = $remote_attachment['real_width']; $height = $remote_attachment['real_height']; $file = $remote_attachment['file']; $filetype = $remote_attachment['type']; if (!in_array($filetype, array('image/jpeg', 'image/gif', 'image/png', 'image/webp'))) return $remote_attachment; if ($filetype == 'image/gif' && $this->isAnimatedGif($file, 'string')) return $remote_attachment; if ( !empty($this->options->qc_asa_filter_maximum_picture_size_width) && !empty($this->options->qc_asa_filter_maximum_picture_size_height) && ($width > $this->options->qc_asa_filter_maximum_picture_size_width || $height > $this->options->qc_asa_filter_maximum_picture_size_height) ) { $remote_attachment['too-large'] = 1; } elseif ( !empty($this->options->qc_asa_filter_maximum_picture_size_width) && empty($this->options->qc_asa_filter_maximum_picture_size_height) && $width > $this->options->qc_asa_filter_maximum_picture_size_width ) { $remote_attachment['too-large'] = 1; } elseif ( empty($this->options->qc_asa_filter_maximum_picture_size_width) && !empty($this->options->qc_asa_filter_maximum_picture_size_height) && $height > $this->options->qc_asa_filter_maximum_picture_size_height ) { $remote_attachment['too-large'] = 1; } else { $remote_attachment['too-large'] = 0; } if ($remote_attachment['too-large']) { if ($width > $height) { $maximum_picture_size_width = empty($this->options->qc_asa_filter_maximum_picture_size_width) ? $width*$this->options->qc_asa_filter_maximum_picture_size_height/$height : $this->options->qc_asa_filter_maximum_picture_size_width; $new_width = intval($maximum_picture_size_width); $new_height = intval($height*$maximum_picture_size_width/$width); } else { $maximum_picture_size_height = empty($this->options->qc_asa_filter_maximum_picture_size_height) ? $height*$this->options->qc_asa_filter_maximum_picture_size_width/$width : $this->options->qc_asa_filter_maximum_picture_size_height; $new_width = intval($width*$maximum_picture_size_height/$height); $new_height = intval($maximum_picture_size_height); } $layer = ImageWorkshop::initFromString($file); if ($filetype=='image/gif' && GifFrameExtractor\GifFrameExtractor::isAnimatedGif($this->temp)) { $gfe = new GifFrameExtractor\GifFrameExtractor(); $frames = $gfe->extract($this->temp, true); $retouchedFrames = array(); foreach ($frames as $frame) { $frameLayer = ImageWorkshop::initFromResourceVar($frame['image']); $frameLayer->resizeInPixel($new_width, $new_height); $retouchedFrames[] = $frameLayer->getResult(); } $gc = new GifCreator\GifCreator(); $gc->create($retouchedFrames, $gfe->getFrameDurations(), 0); $file = $gc->getGif(); } else { $image_p = imagecreatetruecolor($new_width, $new_height); $image = imagecreatefromstring($file); imagecopyresampled($image_p, $image, 0, 0, 0, 0, $new_width, $new_height, $width, $height); ob_start(); switch ($filetype) { case 'image/jpeg': ImageJpeg($image_p, null, $this->options->qc_compression_quality); break; case 'image/png': imagealphablending($image_p, false); imagesavealpha($image_p, true); ImagePng($image_p); break; case 'image/gif': ImageGif($image_p, null); break; case 'image/webp': ImageWebp($image_p, null, $this->options->qc_compression_quality); break; } $file = ob_get_contents(); ob_end_clean(); } imagedestroy($image_p); imagedestroy($layer->getResult()); if ($file) { $remote_attachment['file'] = $file; $remote_attachment['length'] = strlen($file); $remote_attachment['real_width'] = $new_width; $remote_attachment['real_height'] = $new_height; $remote_attachment['resized'] = true; } } return $remote_attachment; } public function fetch_images_from_value($data) { if (empty($data)) return $data; if (is_array($data)) return array_map(array($this, 'fetch_images_from_value'), $data); if ($this->save_type == 'id') { if (preg_match('/^https?:\/\//i', $data) && $this->is_remote_attachment($data)) { do_action( 'qqworld-collector-log', $this->log_id, 'Find remote attachment from post meta ($data):', print_r($data, true) ); $headers = apply_filters( 'qqworld-collector-get-headers-from-url', $data, $this->download_args); $type = $this->get_header($headers); $type = $this->parse_file_type($type, $data); $content_type = preg_replace('/\/.*/i', '', $type); if (!$this->options->qc_asa_general_type || !in_array($content_type, $this->options->qc_asa_general_type)) return $data; $length = $this->get_header($headers, 'Content-Length'); $attachment = array( 'url' => $data, 'type' => $type, 'length' => $length, 'from' => 'img', 'too-small' => 0, 'ignore' => 0, 'alt' => '', 'crc' =>